// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    ERCDDAToken c;
    function setUp() public { c = new ERCDDAToken(0, "", ""); }
    function testFuzz_property(address target, uint256 amount) public {
        vm.assume(target != address(0));
        vm.assume(amount > 0 && amount <= type(uint256).max / 2);
        vm.prank(c.owner());
        c.mintToken(target, amount);
        uint256 sum = c.balanceOf(c.owner()) + c.balanceOf(target);
        assertTrue(c.totalSupply() == sum);
    }
}
